-- Production data model outline for MercDeal.
-- Implement RLS and server-side validation before enabling real transactions.
create table if not exists public.listings (id uuid primary key default gen_random_uuid(), seller_id uuid, title text not null, category text not null, sale_mode text not null, initial_price numeric, minimum_price numeric, daily_drop numeric, duration_days int, status text default 'active', created_at timestamptz default now());
create table if not exists public.offers (id uuid primary key default gen_random_uuid(), listing_id uuid references public.listings(id), buyer_id uuid, amount numeric not null, status text default 'pending', created_at timestamptz default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), listing_id uuid references public.listings(id), buyer_id uuid, seller_id uuid, delivery_mode text not null, item_amount numeric, shipping_amount numeric, total_amount numeric, status text default 'pending', created_at timestamptz default now());
